"use strict";(self.webpackChunkbil_quran=self.webpackChunkbil_quran||[]).push([[40],{40(e){e.exports=JSON.parse('{"font":"Font","lang":"Language","add":"Add","cancel":"Cancel","settings":"Settings","bookmarks_and_notes":"Bookmarks and Notes","bookmark":"Bookmark","note":"Note","highlight":"Highlight","exegesis":"Exegesis","about":{"title":"About","version":"Version","released":"Released","source":"Source"},"lookup":{"title":"Verse lookup","go":"Go"},"locale":{"ar-IQ":"Arabic (Iraqi)","en-US":"English (American)","id-ID":"Indonesian"},"theme":{"title":"Theme","light":"Light","dark":"Dark"},"basmalaPosition":{"0":"Embedded","1":"Detached","title":"Basmala position"},"showPageIndicator":{"title":"Show page indicator","helper":"Show how far your reading has been relatively to part-by-part (the juz) of the Holy Qur\'an"},"alphabeticalChaptersSorting":{"title":"Alphabetical chapters sorting","helper":"Sort chapters neatly, A to Z"},"showTransliteration":{"title":"Show transliteration","helper":"Show a Latin-script transliteration under each Arabic word"},"fontCategory":{"shaddaStacked":"Shadda-stacked","shaddaSeparable":"Allow diacritics separation","helper":"Some fonts keep kasrah below when combined with shaddah"},"fontOptions":{"meQuranLearner":"MeQuran (for Learner)"},"searchSheet":{"byChapter":"By chapter","byJuz":"By juz (part)","juz":"Juz","pageAbbreviation":"pg."},"backup":{"title":"Backup","export":{"title":"Export your data","description":"Copy or download an encoded backup of your bil-Qur\'an settings, notes, and other data.","copy":"Copy","download":"Download","copySuccess":"Copied to clipboard","copyFailed":"Failed to copy"},"import":{"title":"Import your data","description":"Paste your encoded data here","import":"Import","selectFile":"Select file","invalid":"This doesn\'t look like a valid backup file"}},"dialog":{"noteVerse":{"title":"Note this verse","input":{"placeholder":"Optionally add some note..."}},"highlightVerse":{"title":"Highlight this verse","colorLabel":"Color"}},"highlightColor":{"1":"Green","2":"Yellow","3":"Red"},"highlightAction":"Highlight","removeHighlight":"Remove highlight","thoughtSchool":{"100":"Ja\'fari","200":"Salafi","210":"Hanafi","220":"Shafi\'i"},"sajdah":{"title":"Mark prostration verse","wajib":"Obligatory","mustahab":"Recommended","about":{"entryTitle":"Prostration Verses","desc":{"general":"Prostration verses are verses in the Qur\'an whose recitation calls for an immediate act of prostration. Such prostration is known as *sajdah tilawat*, whereby *tilawat* means the recitation of the Qur\'an and reflection on it. It is a direct, physical response to the divine word, and Islamic schools of thought differ on which verses require it and how binding the act is, detailed by school below.","generalSunni":"In the Hanafi school, sajdah tilawat is wajib (obligatory): intentionally missing a sajdah verse without a valid reason is sinful, though a missed sajdah may still be made up later. Hanafi jurisprudence recognizes 14 sajdah locations, including <{[\\"Q\\",\\"38:24\\"]}> (Surah Sad), and does not count <{[\\"Q\\",\\"22:77\\"]}> as a separate sajdah.\\n\\nIn the Shafi\'i school, sajdah tilawat is mustahab (recommended): there is no sin in leaving it, but performing it earns significant reward. Shafi\'i jurisprudence recognizes 14 sajdah locations, including <{[\\"Q\\",\\"22:77\\"]}> (the second sajdah of Surah Al-Hajj), and excludes <{[\\"Q\\",\\"38:24\\"]}>.\\n\\nHow to perform sajdah tilawah:\\n\\n1. Recognise the verse: upon reaching or hearing an ayah of sajdah, pause recitation immediately.\\n2. Face the Qibla: if possible, turn to face the direction of prayer.\\n3. Say Allahu Akbar: pronounce the takbir and descend into sujood without performing ruku first.\\n4. Recite in sujood: say *Subhana Rabbiya al-A\'la* at minimum; the specific dua of sajdah tilawat may also be added.\\n5. Rise with Allahu Akbar: return to an upright position, saying the takbir, then resume recitation.\\n\\nThere is no tashahud, salam, or additional rak\'ah required; sajdah tilawat is a single, standalone prostration. Wudu is required in both the Hanafi and Shafi\'i schools; if in a state of impurity, note the verse and perform the sajdah later once in wudu.","generalShia":"In Twelver Shi\'a jurisprudence, four surahs, <{[\\"Q\\",\\"32:15\\"]}>, <{[\\"Q\\",\\"41:38\\"]}>, <{[\\"Q\\",\\"53:62\\"]}>, and <{[\\"Q\\",\\"96:19\\"]}>, are known as the \'Aza\'im (from *\'azima*, a firm resolve), each containing a verse of obligatory prostration. Reciting or hearing one of these verses makes prostration wajib (immediately obligatory): no wudu, ghusl, facing the qibla, or specific dhikr is required, though the forehead must rest on something valid for prostration, and specific dhikr is recommended. The remaining sajdah verses are treated as mustahab (recommended) rather than obligatory."}}},"privacyPolicy":{"title":"Privacy Policy"},"notice":{"bookmark":{"noDataYet":"No bookmarks yet. Click a verse number to bookmark it or add a note."}},"errors":{"bookmarkCreationFailed":"Failed bookmarking this verse","bookmarkDataNotFound":"Bookmark data not found","bookmarkFetchFailed":"Failed getting all the bookmarked verses","highlightingFailed":"Failed highlighting verse","verseNotFound":"This verse could not be found."}}')}}]);